  async findErasureRequestByIdempotencyKey(merchantId: string, idempotencyKey: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND idempotency_key=$2`,
      [merchantId, idempotencyKey],
    );
    return result.rows[0];
  }

  async createErasureRequest(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow> {
    try {
      const result = await pool.query<ErasureRequestRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key,status)
         VALUES($1,$2,$3,'pending')
         RETURNING *`,
        [merchantId, customerId, idempotencyKey],
      );
      return result.rows[0]!;
    } catch (error: unknown) {
      if (typeof error === 'object' && error !== null && 'code' in error && (error as { code: string }).code === '23505') {
        const existingCust = await this.findErasureRequestByCustomer(merchantId, customerId);
        if (existingCust) return existingCust;
        const existingKey = await this.findErasureRequestByIdempotencyKey(merchantId, idempotencyKey);
