{"path":"/workspace/source/apps/customer-service/src/erasure-processor.ts","command":"create","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { CustomerRepository, type ErasureRequestRow } from './repository.js';

let activeWorkerTrigger: (() => void) | undefined;

export function triggerErasureWorker(): void {
  activeWorkerTrigger?.();
}

export async function processErasure(request: ErasureRequestRow, repository: CustomerRepository): Promise<void> {
  const merchantId = request.merchant_id;
  const customerId = request.customer_id;
  const redis = new Redis(config().REDIS_URL);

  try {
    // 1. MinIO: handle customer imports
    const importRows = await pool.query<{ id: string; object_key: string }>(
      `SELECT id, object_key FROM customers.customer_imports WHERE merchant_id = $1`,
      [merchantId]
    );
    for (const imp of importRows.rows) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, imp.object_key);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) {
          chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
        }
        const text = Buffer.concat(chunks).toString('utf8');
        if (text.includes(customerId)) {
          await objectStore.removeObject(DOCUMENT_BUCKET, imp.object_key).catch(() => {});
          await pool.query(
            `DELETE FROM operations.document_manifests WHERE merchant_id = $1 AND object_key = $2`,
            [merchantId, imp.object_key]
          );
          await pool.query(
            `DELETE FROM customers.customer_imports WHERE merchant_id = $1 AND id = $2`,
            [merchantId, imp.id]
          );
        }
      } catch {
        // Continue if object already deleted or unreadable
      }
    }

    // 2. MinIO & Database: Receipts redaction
    const paymentRows = await pool.query<{ id: string; amount: string; currency: string; created_at: Date }>(
      `SELECT id, amount, currency, created_at FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId]
    );
    for (const payment of paymentRows.rows) {
      const objectKey = `${merchantId}/receipts/${payment.id}.json`;
      const manifestCheck = await pool.query(
        `SELECT 1 FROM operations.document_manifests WHERE merchant_id = $1 AND object_key = $2`,
        [merchantId, objectKey]
      );
      if (manifestCheck.rowCount && manifestCheck.rowCount > 0) {
        const body = JSON.stringify({
          receiptNumber: payment.id,
          issuedAt: payment.created_at.toISOString(),
          customer: { redacted: true },
          amount: Number(payment.amount),
          currency: payment.currency,
        });
        await objectStore.putObject(DOCUMENT_BUCKET, objectKey, body, Buffer.byteLength(body), {
          'Content-Type': 'application/json',
        });
        const checksum = createHash('sha256').update(body).digest('hex');
        await pool.query(
          `UPDATE operations.document_manifests
           SET checksum = $1, metadata = '{"redacted": true}'::jsonb
           WHERE merchant_id = $2 AND object_key = $3`,
          [checksum, merchantId, objectKey]
        );
      }
    }

    // 3. MinIO & Database: Invoices redaction
    const invoiceRows = await pool.query<{ id: string; number: string; currency: string; subtotal: string; tax: string; total: string; issued_at: Date | null; object_key: string | null }>(
      `SELECT id, number, currency, subtotal, tax, total, issued_at, object_key FROM payments.invoices WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId]
    );
    for (const inv of invoiceRows.rows) {
      if (inv.object_key) {
        const linesResult = await pool.query<{ description: string; quantity: number; unit_amount: string; total: string }>(
          `SELECT description, quantity, unit_amount, total FROM payments.invoice_lines WHERE invoice_id = $1`,
          [inv.id]
        );
        const body = JSON.stringify({
          invoiceId: inv.id,
          number: inv.number,
          customer: { redacted: true },
          currency: inv.currency,
          subtotal: Number(inv.subtotal),
          tax: Number(inv.tax),
          total: Number(inv.total),
          lines: linesResult.rows.map((l) => ({
            description: l.description,
            quantity: l.quantity,
            unitAmount: Number(l.unit_amount),
          })),
          issuedAt: inv.issued_at ? inv.issued_at.toISOString() : new Date().toISOString(),
        });
        await objectStore.putObject(DOCUMENT_BUCKET, inv.object_key, body, Buffer.byteLength(body), {
          'Content-Type': 'application/json',
        });
        const checksum = createHash('sha256').update(body).digest('hex');
        await pool.query(
          `UPDATE operations.document_manifests SET checksum = $1 WHERE merchant_id = $2 AND object_key = $3`,
          [checksum, merchantId, inv.object_key]
        );
      }
    }

    // 4. Database cleanup in transaction
    await transaction(async (client) => {
      // Delete customer child tables
      await client.query(`DELETE FROM customers.addresses WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM customers.contacts WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id = $1 AND payflow_customer_id = $2`, [merchantId, customerId]);

      // Support messages & participants & tickets
      await client.query(
        `DELETE FROM customers.support_messages WHERE merchant_id = $1 AND (author_id = $2 OR ticket_id IN (SELECT ticket_id FROM customers.support_participants WHERE customer_id = $2))`,
        [merchantId, customerId]
      );
      await client.query(`DELETE FROM customers.support_participants WHERE customer_id = $1`, [customerId]);
      await client.query(
        `DELETE FROM customers.support_tickets WHERE merchant_id = $1 AND id NOT IN (SELECT ticket_id FROM customers.support_participants)`,
        [merchantId]
      );

      // Operations tables
      await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM operations.notifications WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(`DELETE FROM operations.analytics_events WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
      await client.query(
        `DELETE FROM operations.jobs WHERE merchant_id = $1 AND status = 'pending' AND payload->>'customerId' = $2`,
        [merchantId, customerId]
      );
      await client.query(
        `DELETE FROM operations.outbox_events WHERE merchant_id = $1 AND status = 'pending' AND (aggregate_id = $2 OR payload->>'customerId' = $2)`,
        [merchantId, customerId]
      );
      await client.query(
        `UPDATE platform.audit_logs SET metadata = '{"redacted": true}'::jsonb WHERE merchant_id = $1 AND target_type = 'customer' AND target_id = $2`,
        [merchantId, customerId]
      );

      // Financial redactions
      await client.query(
        `UPDATE payments.payment_intents SET customer_snapshot = '{"redacted": true}'::jsonb, description = NULL, updated_at = now() WHERE merchant_id = $1 AND customer_id = $2`,
        [merchantId, customerId]
      );
      await client.query(
        `UPDATE payments.payment_attempts SET request_payload = '{"redacted": true}'::jsonb, response_payload = '{"redacted": true}'::jsonb WHERE merchant_id = $1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id = $2)`,
        [merchantId, customerId]
      );
      await client.query(
        `UPDATE payments.refunds SET customer_email = NULL WHERE merchant_id = $1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id = $2)`,
        [merchantId, customerId]
      );
      await client.query(
        `UPDATE payments.invoices SET billing_snapshot = '{"redacted": true}'::jsonb WHERE merchant_id = $1 AND customer_id = $2`,
        [merchantId, customerId]
      );

      // Finally delete customer row
      await client.query(`DELETE FROM customers.customers WHERE merchant_id = $1 AND id = $2`, [merchantId, customerId]);
    });

    // 5. OpenSearch deletion
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` }).catch(() => {});
    await searchClient.indices.refresh({ index: CUSTOMER_INDEX }).catch(() => {});

    // 6. Redis deletion & tombstone
    await redis.del(`merchant:${merchantId}:customer:${customerId}`, `merchant:${merchantId}:customer:${customerId}:activity`);
    await redis.set(`erased:customer:${customerId}`, '1', 'EX', 86400 * 30);

    // 7. Complete request
    await repository.completeErasureRequest(request.id);
  } catch (error) {
    logger.error({ error, requestId: request.id }, 'erasure processing failed');
    await repository.failErasureRequest(request.id, 'cleanup_failed');
    throw error;
  } finally {
    await redis.quit().catch(() => {});
  }
}

export function startErasureWorker(signal: AbortSignal, repository = new CustomerRepository()): void {
  const workerId = `customer-erasure-worker-${randomUUID()}`;
  let running = false;

  const tick = async () => {
    if (running || signal.aborted) return;
    running = true;
    try {
      while (!signal.aborted) {
        const claimed = await repository.claimNextErasureRequest(workerId);
        if (!claimed) break;
        await processErasure(claimed, repository);
      }
    } catch (error) {
      logger.error({ error, workerId }, 'erasure worker tick failed');
    } finally {
      running = false;
    }
  };

  activeWorkerTrigger = () => {
    void tick();
  };

  const timer = setInterval(() => { void tick(); }, 250);
  signal.addEventListener('abort', () => {
    clearInterval(timer);
    activeWorkerTrigger = undefined;
  });
  void tick();
}
"}

