import { triggerErasureWorker } from './erasure-processor.js';

export class CustomerService {
  constructor(private readonly repository = new CustomerRepository()) {}

  async requestErasure(merchantId: string, customerId: string, idempotencyKey: string): Promise<Record<string, unknown>> {
    const existing = await this.repository.findErasureRequestByCustomer(merchantId, customerId);
    if (existing) {
      if (existing.status === 'failed') {
        const retried = await this.repository.retryErasureRequest(existing.id);
        triggerErasureWorker();
        return this.formatErasure(retried);
      }
      return this.formatErasure(existing);
    }

    const existingByKey = await this.repository.findErasureRequestByIdempotencyKey(merchantId, idempotencyKey);
    if (existingByKey) {
      throw Object.assign(new Error('idempotency conflict'), { statusCode: 409 });
    }

    const customer = await this.repository.find(merchantId, customerId);
    if (!customer) {
      throw Object.assign(new Error('customer not found'), { statusCode: 404 });
    }

    const created = await this.repository.createErasureRequest(merchantId, customerId, idempotencyKey);
    triggerErasureWorker();
    return this.formatErasure(created);
  }

  async getErasureRequest(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
    const row = await this.repository.findErasureRequest(merchantId, requestId);
    if (!row) return undefined;
    return this.formatErasure(row);
  }

  private formatErasure(row: ErasureRequestRow): Record<string, unknown> {
    return {
      id: row.id,
      customerId: row.customer_id,
      status: row.status,
      attempts: row.attempts,
      createdAt: row.created_at.toISOString(),
      updatedAt: row.updated_at.toISOString(),
      completedAt: row.completed_at ? row.completed_at.toISOString() : null,
      lastError: row.last_error ?? null,
    };
  }","path":"/workspace/source/apps/customer-service/src/service.ts","command":"str_replace","old_str":"import {
