import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const secondApiKey = 'pf_local_dev_bluebird_924bd90d2201';

async function api<T = Record<string, unknown>>(
  path: string,
  method = 'GET',
  body?: unknown,
  key = apiKey,
  extraHeaders: Record<string, string> = {},
): Promise<{ status: number; body: T }> {
  const headers: Record<string, string> = { authorization: `Bearer ${key}`, ...extraHeaders };
  const init: RequestInit = { method, headers };
  if (body !== undefined) {
    headers['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  let responseBody: unknown;
  try {
    responseBody = await response.json();
  } catch {
    responseBody = undefined;
  }
  return { status: response.status, body: responseBody as T };
}

async function waitForErasure(requestId: string, targetStatus = 'completed', key = apiKey): Promise<Record<string, unknown>> {
  for (let i = 0; i < 40; i++) {
    const res = await api<Record<string, unknown>>(`/v1/erasure-requests/${requestId}`, 'GET', undefined, key);
    if (res.body?.status === targetStatus) return res.body;
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
  throw new Error(`Erasure request ${requestId} did not reach status ${targetStatus}`);
}

