test('POST /v1/customers/:customerId/erasure-requests idempotency and conflict behavior', async () => {
  const custA = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `idemp-a-${randomUUID()}`,
    email: `idemp-a-${randomUUID()}@example.test`,
    name: 'Idempotency Customer A',
  });
  assert.equal(custA.status, 201);

  const custB = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `idemp-b-${randomUUID()}`,
    email: `idemp-b-${randomUUID()}@example.test`,
    name: 'Idempotency Customer B',
  });
  assert.equal(custB.status, 201);

  const sharedKey = `shared-key-${randomUUID()}`;

  // 1. Initial request for customer A
  const res1 = await api<{ id: string; customerId: string; status: string; attempts: number }>(
    `/v1/customers/${custA.body.id}/erasure-requests`,
    'POST',
    undefined,
    apiKey,
    { 'idempotency-key': sharedKey },
  );
  assert.equal(res1.status, 202);
  assert.equal(res1.body.customerId, custA.body.id);
  assert.ok(res1.body.id);

  // 2. Reusing same key for same customer -> returns same request
  const resReplay = await api<{ id: string; customerId: string }>(
    `/v1/customers/${custA.body.id}/erasure-requests`,
    'POST',
    undefined,
    apiKey,
    { 'idempotency-key': sharedKey },
  );
  assert.equal(resReplay.status, 202);
  assert.equal(resReplay.body.id, res1.body.id);

  // 3. Reusing same key for different customer -> 409 Conflict
  const resConflict = await api(
    `/v1/customers/${custB.body.id}/erasure-requests`,
    'POST',
    undefined,
    apiKey,
    { 'idempotency-key': sharedKey },
  );
  assert.equal(resConflict.status, 409);

  // 4. New key for customer who already has an erasure request -> returns existing request
  const newKey = `new-key-${randomUUID()}`;
  const resNewKey = await api<{ id: string }>(
    `/v1/customers/${custA.body.id}/erasure-requests`,
    'POST',
    undefined,
    apiKey,
    { 'idempotency-key': newKey },
  );
  assert.equal(resNewKey.status, 202);
  assert.equal(resNewKey.body.id, res1.body.id);
});

