test('Full customer lifecycle deletion and financial data retention', async () => {
  const suffix = randomUUID();
  const person = {
    externalReference: `full-test-${suffix}`,
    email: `full.test.${suffix}@example.test`,
    name: 'Full Lifecycle Customer',
    phone: '+1-555-0199',
  };

  // 1. Create customer
  const customerRes = await api<{ id: string }>('/v1/customers', 'POST', person);
  assert.equal(customerRes.status, 201);
  const customerId = customerRes.body.id;

  // 2. Add address and contact
  await api(`/v1/customers/${customerId}/addresses`, 'POST', {
    kind: 'billing',
    line1: '123 Privacy Lane',
    city: 'San Francisco',
    region: 'CA',
    postalCode: '94105',
    country: 'US',
  });
  await api(`/v1/customers/${customerId}/contacts`, 'POST', {
    kind: 'email',
    value: person.email,
    isPrimary: true,
  });

  // 3. Attach payment method
  const methodRes = await api<{ id: string }>(`/v1/customers/${customerId}/payment-methods`, 'POST', {
    providerToken: `tok_test_${suffix}`,
    type: 'card',
    brand: 'visa',
    last4: '1111',
    billingName: person.name,
    billingAddress: { line1: '123 Privacy Lane', city: 'San Francisco', country: 'US' },
  });
  assert.equal(methodRes.status, 201);

  // 4. Create support ticket
  await api(`/v1/customers/${customerId}/support-tickets`, 'POST', {
    subject: 'Privacy inquiry',
    body: `Please remove all data for ${person.email}`,
  });

  // 5. Customer import
  await api('/v1/customer-imports', 'POST', {
    source: 'legacy-import',
    record: { customerId, ...person },
  });

  // 6. Create invoice
  const invoiceRes = await api<{ id: string; objectKey: string }>('/v1/invoices', 'POST', {
    customerId,
    currency: 'USD',
    tax: 200,
    lines: [{ description: 'Annual Subscription', quantity: 1, unitAmount: 10000 }],
  });
  assert.equal(invoiceRes.status, 201);

  // 7. Create payment
  const paymentRes = await api<{ id: string }>('/v1/payments', 'POST', {
    customerId,
    paymentMethodId: methodRes.body.id,
    amount: 5000,
    currency: 'USD',
    description: `Payment for ${person.name}`,
  }, apiKey, { 'idempotency-key': `full-pay-${suffix}` });
  assert.equal(paymentRes.status, 202);
  const paymentId = paymentRes.body.id;

  // Wait for payment processing to settle
  await new Promise((r) => setTimeout(r, 2000));

  // 8. Create refund
  await api(`/v1/payments/${paymentId}/refunds`, 'POST', {
    amount: 1000,
    reason: 'Customer refund request',
  });
  await new Promise((r) => setTimeout(r, 1000));

  // Verify active projections exist before erasure
  const redis = new Redis(config().REDIS_URL);
  const cachedCustomer = await redis.get(`merchant:10000000-0000-4000-8000-000000000001:customer:${customerId}`);
  assert.ok(cachedCustomer, 'Expected customer in Redis projection before erasure');

  const searchBefore = await searchClient.get({
    index: CUSTOMER_INDEX,
    id: `10000000-0000-4000-8000-000000000001:${customerId}`,
  }).catch(() => undefined);
  assert.ok(searchBefore?.body?._source, 'Expected customer in OpenSearch before erasure');

  // 9. Request data deletion
  const eraseRes = await api<{ id: string }>(
    `/v1/customers/${customerId}/erasure-requests`,
    'POST',
    undefined,
    apiKey,
    { 'idempotency-key': `erase-full-${suffix}` },
  );
  assert.equal(eraseRes.status, 202);

  const completed = await waitForErasure(eraseRes.body.id);
  assert.equal(completed.status, 'completed');

  // 10. VERIFICATIONS AFTER ERASURE

  // Customer API endpoints return 404
  const getCustomer = await api(`/v1/customers/${customerId}`);
  assert.equal(getCustomer.status, 404);

  // Customer list does not include customer
  const listCustomers = await api<{ data: Array<{ id: string }> }>('/v1/customers');
  assert.ok(!listCustomers.body.data.some((c) => c.id === customerId));

  // Database customer child tables are empty
  const addresses = await pool.query('SELECT 1 FROM customers.addresses WHERE customer_id = $1', [customerId]);
  assert.equal(addresses.rowCount, 0);
  const contacts = await pool.query('SELECT 1 FROM customers.contacts WHERE customer_id = $1', [customerId]);
  assert.equal(contacts.rowCount, 0);
  const paymentMethods = await pool.query('SELECT 1 FROM customers.payment_method_refs WHERE customer_id = $1', [customerId]);
  assert.equal(paymentMethods.rowCount, 0);
  const providerMappings = await pool.query('SELECT 1 FROM customers.provider_customer_mappings WHERE customer_id = $1', [customerId]);
  assert.equal(providerMappings.rowCount, 0);
  const sandboxCustomers = await pool.query('SELECT 1 FROM provider_sandbox.customers WHERE payflow_customer_id = $1', [customerId]);
  assert.equal(sandboxCustomers.rowCount, 0);

  // Redis projections deleted & tombstone set
  const redisCustomerAfter = await redis.get(`merchant:10000000-0000-4000-8000-000000000001:customer:${customerId}`);
  assert.equal(redisCustomerAfter, null);
  const redisActivityAfter = await redis.exists(`merchant:10000000-0000-4000-8000-000000000001:customer:${customerId}:activity`);
  assert.equal(redisActivityAfter, 0);
  const redisTombstone = await redis.get(`erased:customer:${customerId}`);
  assert.equal(redisTombstone, '1');

  // OpenSearch document deleted
  const searchAfter = await searchClient.get({
    index: CUSTOMER_INDEX,
    id: `10000000-0000-4000-8000-000000000001:${customerId}`,
  }).catch(() => undefined);
  assert.equal(searchAfter, undefined);

  // Financial records RETAINED and financially consistent, but PII redacted:
  // Payment Intent
  const paymentDb = await pool.query<{ amount: string; currency: string; status: string; customer_snapshot: Record<string, unknown>; description: string | null }>(
    'SELECT amount, currency, status, customer_snapshot, description FROM payments.payment_intents WHERE id = $1',
    [paymentId],
  );
  assert.equal(paymentDb.rows[0]?.amount, '5000');
  assert.equal(paymentDb.rows[0]?.currency, 'USD');
  assert.equal(paymentDb.rows[0]?.description, null);
  assert.deepEqual(paymentDb.rows[0]?.customer_snapshot, { redacted: true });

  // Refund
  const refundDb = await pool.query<{ amount: string; customer_email: string | null }>(
    'SELECT amount, customer_email FROM payments.refunds WHERE payment_intent_id = $1',
    [paymentId],
  );
  assert.equal(refundDb.rows[0]?.amount, '1000');
  assert.equal(refundDb.rows[0]?.customer_email, null);

  // Invoice
  const invoiceDb = await pool.query<{ total: string; billing_snapshot: Record<string, unknown> }>(
    'SELECT total, billing_snapshot FROM payments.invoices WHERE id = $1',
    [invoiceRes.body.id],
  );
  assert.equal(invoiceDb.rows[0]?.total, '10200');
  assert.deepEqual(invoiceDb.rows[0]?.billing_snapshot, { redacted: true });

  // MinIO Receipt: exists and has redacted customer
  const receiptKey = `10000000-0000-4000-8000-000000000001/receipts/${paymentId}.json`;
  const receiptStream = await objectStore.getObject(DOCUMENT_BUCKET, receiptKey);
  const receiptChunks: Buffer[] = [];
  for await (const chunk of receiptStream) receiptChunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  const receiptJson = JSON.parse(Buffer.concat(receiptChunks).toString('utf8')) as { amount: number; customer: unknown };
  assert.equal(receiptJson.amount, 5000);
  assert.deepEqual(receiptJson.customer, { redacted: true });

  // MinIO Invoice: exists and has redacted customer
  const invStream = await objectStore.getObject(DOCUMENT_BUCKET, invoiceRes.body.objectKey);
  const invChunks: Buffer[] = [];
  for await (const chunk of invStream) invChunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  const invJson = JSON.parse(Buffer.concat(invChunks).toString('utf8')) as { total: number; customer: unknown };
  assert.equal(invJson.total, 10200);
  assert.deepEqual(invJson.customer, { redacted: true });

  await redis.quit();
});
